  kam_id = excluded.kam_id,
  client_id = excluded.client_id,
  requested_at = excluded.requested_at,
  request_date = excluded.request_date,
  sells_currency = excluded.sells_currency,
  gets_currency = excluded.gets_currency,
  amount = excluded.amount,
  rate = excluded.rate,
  note = coalesce(public.requests.note, excluded.note),
  legacy_status = excluded.legacy_status,
  source = 'import';

insert into public.requests (
  kam_id, client_id, requested_at, request_date,
  sells_currency, gets_currency, amount, rate, note,
  source, legacy_status, import_key
)
